import os
from collections import Counter

counts = Counter()
with open(os.path.join("дані", "лог.txt"), encoding="utf-8") as f:
    for line in f:
        parts = line.split(None, 2)
        if len(parts) < 2 or parts[1] != "ERROR":
            continue
        t = parts[0]
        if "T" not in t:
            continue
        hour = t.split("T", 1)[1][:2]
        if hour.isdigit():
            counts[int(hour)] += 1

for h in sorted(counts):
    print(f"{h:02d}: {counts[h]}")
